{
  "task_summary": "Predict whether an individual has public health insurance coverage.",
  "ranking": [
    {
      "rank": 1,
      "feature": "AGEP",
      "rationale": "Directly tied to Medicare, Medicaid, CHIP, and age-based eligibility rules."
    },
    {
      "rank": 2,
      "feature": "PINCP",
      "rationale": "Income is central to means-tested public coverage eligibility."
    },
    {
      "rank": 3,
      "feature": "ESR",
      "rationale": "Employment status affects access to employer insurance and public alternatives."
    },
    {
      "rank": 4,
      "feature": "DIS",
      "rationale": "Disability status is semantically linked to Medicare, Medicaid, and SSI-related coverage."
    },
    {
      "rank": 5,
      "feature": "DREM",
      "rationale": "Cognitive difficulty is a strong disability-related eligibility signal."
    },
    {
      "rank": 6,
      "feature": "MIL",
      "rationale": "Military service can indicate eligibility for VA or other public coverage."
    },
    {
      "rank": 7,
      "feature": "SCHL",
      "rationale": "Education captures stable socioeconomic differences related to insurance access."
    },
    {
      "rank": 8,
      "feature": "CIT",
      "rationale": "Citizenship affects eligibility for several public insurance programs."
    },
    {
      "rank": 9,
      "feature": "MAR",
      "rationale": "Marital status affects household resources and potential dependent coverage."
    },
    {
      "rank": 10,
      "feature": "ESP",
      "rationale": "Parental employment status is relevant for children's coverage and household access."
    },
    {
      "rank": 11,
      "feature": "DEAR",
      "rationale": "Hearing difficulty is a disability-related but narrower eligibility signal."
    },
    {
      "rank": 12,
      "feature": "DEYE",
      "rationale": "Vision difficulty is a disability-related but narrower eligibility signal."
    },
    {
      "rank": 13,
      "feature": "MIG",
      "rationale": "Recent mobility may affect continuity of coverage but can be state-specific."
    },
    {
      "rank": 14,
      "feature": "FER",
      "rationale": "Recent fertility may relate to pregnancy or postpartum Medicaid but applies narrowly."
    },
    {
      "rank": 15,
      "feature": "NATIVITY",
      "rationale": "Nativity can affect eligibility indirectly but overlaps with citizenship and demographics."
    },
    {
      "rank": 16,
      "feature": "SEX",
      "rationale": "Sex has limited direct semantic relevance outside pregnancy-related pathways."
    },
    {
      "rank": 17,
      "feature": "RAC1P",
      "rationale": "Race may reflect structural disparities but risks demographic shortcut learning."
    },
    {
      "rank": 18,
      "feature": "ANC",
      "rationale": "Ancestry is mostly a demographic and geographic proxy with brittle associations."
    },
    {
      "rank": 19,
      "feature": "ST",
      "rationale": "State encodes geography and policy artifacts that are especially brittle for OOD generalization."
    }
  ]
}
